-- PostgreSQL reference schema for the EXTERNAL website. Not a Replit migration.
-- UUIDs are generated by the server application; all timestamps use UTC.
BEGIN;

CREATE TABLE app_users (
  user_id uuid PRIMARY KEY,
  email varchar(254) NOT NULL,
  password_hash text, -- Argon2id encoded hash; nullable for federated/token-only accounts.
  external_identity_id text UNIQUE,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX app_users_email_unique ON app_users (lower(email));

CREATE TABLE app_entitlements (
  user_id uuid PRIMARY KEY REFERENCES app_users(user_id) ON DELETE CASCADE,
  product text NOT NULL DEFAULT 'social-najhin' CHECK (product = 'social-najhin'),
  access_model text NOT NULL DEFAULT 'perpetual' CHECK (access_model IN ('perpetual', 'subscription')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'revoked')),
  max_devices integer NOT NULL DEFAULT 1 CHECK (max_devices BETWEEN 1 AND 500),
  support_until timestamptz,
  purchased_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- Do NOT auto-create an entitlement on signup or trust any desktop-submitted payment state.
-- Only trusted purchase/admin/billing logic grants or changes access.

CREATE TABLE app_subscriptions (
  user_id uuid PRIMARY KEY REFERENCES app_entitlements(user_id) ON DELETE CASCADE,
  status text NOT NULL CHECK (status IN ('trialing', 'active', 'past_due', 'canceled', 'expired')),
  current_period_start timestamptz NOT NULL,
  current_period_end timestamptz NOT NULL,
  cancel_at_period_end boolean NOT NULL DEFAULT false,
  provider text,
  provider_subscription_id text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (current_period_end > current_period_start),
  UNIQUE (provider, provider_subscription_id)
);
-- No row maps to API subscription.status='none'.
-- One current subscription per user; keep provider event/history separately.

CREATE TABLE app_devices (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(user_id) ON DELETE CASCADE,
  device_id char(64) NOT NULL CHECK (device_id ~ '^[a-f0-9]{64}$'),
  name varchar(128) NOT NULL CHECK (length(name) > 0),
  platform text NOT NULL CHECK (platform IN ('win32', 'darwin', 'linux')),
  app_version varchar(64) NOT NULL CHECK (length(app_version) > 0),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'revoked', 'blocked')),
  activated_at timestamptz,
  revoked_at timestamptz,
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, device_id),
  UNIQUE (id, user_id),
  CHECK (status <> 'active' OR activated_at IS NOT NULL)
);
CREATE INDEX app_devices_active_count ON app_devices(user_id) WHERE status = 'active';

CREATE TABLE app_desktop_sessions (
  session_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(user_id) ON DELETE CASCADE,
  device_row_id uuid NOT NULL,
  access_token_hash char(64) NOT NULL UNIQUE CHECK (access_token_hash ~ '^[a-f0-9]{64}$'),
  access_expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL, -- Absolute 30 days from login, not sliding.
  revoked_at timestamptz,
  FOREIGN KEY (device_row_id, user_id) REFERENCES app_devices(id, user_id) ON DELETE CASCADE,
  CHECK (expires_at > created_at),
  CHECK (access_expires_at <= expires_at)
);
CREATE INDEX app_desktop_sessions_device ON app_desktop_sessions(device_row_id);

CREATE TABLE app_refresh_tokens (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES app_desktop_sessions(session_id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  issued_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  revoked_at timestamptz,
  replaced_by uuid REFERENCES app_refresh_tokens(id),
  CHECK (expires_at > issued_at)
);
CREATE INDEX app_refresh_tokens_session ON app_refresh_tokens(session_id);
-- Retain consumed token hashes until session expiry for replay detection.
-- Rotation locks the session and token rows, consumes old token, creates successor,
-- updates access_token_hash/expires_at, and commits as ONE transaction.
-- On replay COMMIT family revocation before responding 401; do not roll it back.

CREATE TABLE app_personal_login_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(user_id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  scope text NOT NULL DEFAULT 'desktop:login' CHECK (scope = 'desktop:login'),
  label varchar(128) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  last_used_at timestamptz,
  UNIQUE (id, user_id),
  CHECK (expires_at > created_at)
);
-- Token format snp_ + base64url(randomBytes(48)); display once in the website.
-- Store SHA-256 of the complete token, never plaintext. Revoking this token must
-- also revoke sessions created through it (source token FK below).
ALTER TABLE app_desktop_sessions ADD COLUMN login_token_id uuid;
ALTER TABLE app_desktop_sessions ADD CONSTRAINT desktop_session_login_token_owner
  FOREIGN KEY (login_token_id, user_id) REFERENCES app_personal_login_tokens(id, user_id);
CREATE INDEX app_desktop_sessions_login_token ON app_desktop_sessions(login_token_id);

CREATE TABLE app_security_events (
  event_id uuid PRIMARY KEY,
  user_id uuid REFERENCES app_users(user_id) ON DELETE SET NULL,
  event_type text NOT NULL,
  request_id uuid NOT NULL,
  reason_code text,
  created_at timestamptz NOT NULL DEFAULT now()
);
-- No passwords, raw tokens, Authorization headers or request bodies in audit logs.

COMMIT;

-- REQUIRED BUSINESS RULE, not enforced by the device uniqueness constraint:
-- BEGIN;
-- SELECT * FROM app_entitlements WHERE user_id = :authenticated_user FOR UPDATE;
-- Re-evaluate account, entitlement and subscription; absent entitlement -> deny.
-- SELECT * FROM app_devices WHERE id = :session_device FOR UPDATE;
-- If blocked -> deny. If active -> success without allocating another seat.
-- SELECT count(*) FROM app_devices WHERE user_id = :authenticated_user AND status='active';
-- If count >= max_devices -> 409 DEVICE_LIMIT_REACHED, with no device changes.
-- Otherwise mark active, activated_at=now(), revoked_at=NULL, then COMMIT.
--
-- ALL seat mutations (activate, detach, web device management, max_devices edits)
-- must acquire the SAME entitlement lock FIRST. Do not lower max_devices below
-- the active count without an explicit administrative device-revocation policy.
-- User creation and login must not allocate seats.
-- Use prepared statements; :parameters above are pseudocode, not executable SQL.
